        row_bounds.append((start, h))
    if not row_bounds:
        row_bounds = [(0, h)]
    col_bounds = []
    start = 0
    for c in divider_cols:
        if c >= start:
            col_bounds.append((start, c))
            start = c + 1
    if start < w:
        col_bounds.append((start, w))
    if not col_bounds:
        col_bounds = [(0, w)]

    # Pick the panel with the most non-background cells as the pattern.
    panels = []
    for r0, r1 in row_bounds:
        for c0, c1 in col_bounds:
            panel = [row[c0:c1] for row in grid[r0:r1]]
            score = sum(v != background for row in panel for v in row)
            panels.append((score, r0, r1, c0, c1, panel))
    _, sr0, sr1, sc0, sc1, source = max(panels, key=lambda p: p[0])
    out = [row[:] for row in grid]
    sh, sw = sr1 - sr0, sc1 - sc0
    for r0, r1 in row_bounds:
        for c0, c1 in col_bounds:
            if r1-r0 == sh and c1-c0 == sw:
                for i in range(sh):
                    out[r0+i][c0:c1] = source[i][:]
    return out
