def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    background = max(counts, key=counts.get)

    # Uniform lines in the non-background color are panel dividers.
    divider_rows = [r for r in range(h) if len(set(grid[r])) == 1 and grid[r][0] != background]
    divider_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1 and grid[0][c] != background]

    def intervals(length, dividers):
        result, start = [], 0
        for d in dividers:
            if d >= start:
                if start < d:
                    result.append((start, d))
                start = d + 1
        if start < length:
            result.append((start, length))
        return result or [(0, length)]

    rb = intervals(h, divider_rows)
    cb = intervals(w, divider_cols)
    panels = []
    for r0, r1 in rb:
        for c0, c1 in cb:
            panel = [row[c0:c1] for row in grid[r0:r1]]
            score = sum(v != background for row in panel for v in row)
            panels.append((score, r0, r1, c0, c1, panel))
    _, _, _, _, _, source = max(panels, key=lambda p: p[0])
    sh, sw = len(source), len(source[0])
    out = [row[:] for row in grid]
    for r0, r1 in rb:
        for c0, c1 in cb:
            if r1 - r0 == sh and c1 - c0 == sw:
                for i in range(sh):
                    out[r0 + i][c0:c1] = source[i][:]
    return out
